INSERT INTO `video_partitions` (`id`, `created_at`, `updated_at`, `name`, `icon`, `sort_order`, `is_active`, `is_submittable`) VALUES (2, '2026-01-14 14:59:06.711', '2026-03-22 03:16:29.494', '动画', '<svg viewBox=\"0 0 100 100\" xmlns=\"http://www.w3.org/2000/svg\" width=\"100%\" height=\"100%\">\n                  <defs>\n                    <linearGradient id=\"animGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n                      <stop offset=\"0%\" stop-color=\"#FF3366\"></stop>\n                      <stop offset=\"100%\" stop-color=\"#7000FF\"></stop>\n                    </linearGradient>\n                    <filter id=\"glow-anim\" x=\"-50%\" y=\"-50%\" width=\"200%\" height=\"200%\">\n                      <feGaussianBlur stdDeviation=\"4\" result=\"coloredBlur\"></feGaussianBlur>\n                      <feMerge>\n                        <feMergeNode in=\"coloredBlur\"></feMergeNode>\n                        <feMergeNode in=\"SourceGraphic\"></feMergeNode>\n                      </feMerge>\n                    </filter>\n                  </defs>\n                  <style>\n                    .anim-play { transform-origin: center; animation: anim-float 3s ease-in-out infinite; filter: url(#glow-anim); }\n                    .anim-ring1 { transform-origin: center; animation: anim-pulse 2.5s ease-out infinite; stroke-dasharray: 200; stroke-dashoffset: 0; }\n                    .anim-ring2 { transform-origin: center; animation: anim-pulse 2.5s ease-out infinite 1.25s; }\n                    @keyframes anim-float { \n                      0%, 100% { transform: translateY(0) scale(1) rotate(0deg); } \n                      50% { transform: translateY(-4px) scale(1.03) rotate(2deg); } \n                    }\n                    @keyframes anim-pulse { \n                      0% { transform: scale(0.7); opacity: 0.8; stroke-width: 2; } \n                      100% { transform: scale(1.3); opacity: 0; stroke-width: 0.5; } \n                    }\n                  </style>\n                  <circle cx=\"50\" cy=\"50\" r=\"30\" fill=\"none\" stroke=\"url(#animGrad)\" class=\"anim-ring1\"></circle>\n                  <circle cx=\"50\" cy=\"50\" r=\"30\" fill=\"none\" stroke=\"url(#animGrad)\" class=\"anim-ring2\"></circle>\n                  \n                  <path d=\"M42 37 L66 50 L42 63 Z\" fill=\"url(#animGrad)\" class=\"anim-play\" stroke=\"url(#animGrad)\" stroke-width=\"6\" stroke-linejoin=\"round\"></path>\n                  <path d=\"M42 37 L66 50 L42 63 Z\" fill=\"#ffffff\" opacity=\"0.2\" class=\"anim-play\" stroke=\"none\" transform=\"translate(-1, -1)\"></path>\n                </svg>', 1, 1, 1);
INSERT INTO `video_partitions` (`id`, `created_at`, `updated_at`, `name`, `icon`, `sort_order`, `is_active`, `is_submittable`) VALUES (3, '2026-01-14 14:59:06.711', '2026-03-23 20:58:52.440', '音乐', '<svg viewBox=\"0 0 100 100\" xmlns=\"http://www.w3.org/2000/svg\" width=\"100%\" height=\"100%\">\n                  <defs>\n                    <linearGradient id=\"musicGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n                      <stop offset=\"0%\" stop-color=\"#F02FC2\"></stop>\n                      <stop offset=\"100%\" stop-color=\"#6094EA\"></stop>\n                    </linearGradient>\n                    <filter id=\"musicGlow\" x=\"-50%\" y=\"-50%\" width=\"200%\" height=\"200%\">\n                        <feGaussianBlur stdDeviation=\"4\" result=\"blur\"></feGaussianBlur>\n                        <feComposite in=\"SourceGraphic\" in2=\"blur\" operator=\"over\"></feComposite>\n                    </filter>\n                  </defs>\n                  <style>\n                    .music-bar { transform-origin: center bottom; animation: music-eq infinite alternate ease-in-out; fill: url(#musicGrad); opacity: 0.6; }\n                    .b1 { animation-duration: 0.5s; } .b2 { animation-duration: 0.7s; } .b3 { animation-duration: 0.6s; } .b4 { animation-duration: 0.8s; } .b5 { animation-duration: 0.55s; }\n                    .music-disk { transform-origin: 50px 50px; animation: music-spin 8s linear infinite; stroke: url(#musicGrad); fill: none; stroke-width: 1.5; }\n                    .music-note { transform-origin: 50px 50px; animation: music-float 3s infinite alternate ease-in-out; filter: url(#musicGlow); }\n                    @keyframes music-eq { 0% { transform: scaleY(0.2); } 100% { transform: scaleY(1); } }\n                    @keyframes music-spin { to { transform: rotate(360deg); } }\n                    @keyframes music-float { 0% { transform: translateY(3px) rotate(-3deg); } 100% { transform: translateY(-3px) rotate(3deg); } }\n                  </style>\n                  \n                  \n                  <g transform=\"translate(0, -10)\">\n                    <rect x=\"25\" y=\"40\" width=\"6\" height=\"40\" rx=\"3\" class=\"music-bar b1\"></rect>\n                    <rect x=\"37\" y=\"30\" width=\"6\" height=\"50\" rx=\"3\" class=\"music-bar b2\"></rect>\n                    <rect x=\"49\" y=\"20\" width=\"6\" height=\"60\" rx=\"3\" class=\"music-bar b3\"></rect>\n                    <rect x=\"61\" y=\"35\" width=\"6\" height=\"45\" rx=\"3\" class=\"music-bar b4\"></rect>\n                    <rect x=\"73\" y=\"45\" width=\"6\" height=\"35\" rx=\"3\" class=\"music-bar b5\"></rect>\n                  </g>\n                  \n                  \n                  <circle cx=\"50\" cy=\"50\" r=\"38\" class=\"music-disk\" stroke-dasharray=\"12 12\" opacity=\"0.8\"></circle>\n                  <circle cx=\"50\" cy=\"50\" r=\"30\" class=\"music-disk\" stroke-dasharray=\"30 15\" opacity=\"0.4\" style=\"animation-direction: reverse; animation-duration: 12s;\"></circle>\n                  \n                  \n                  <g class=\"music-note\" transform=\"translate(0, 5)\">\n                    \n                    <path d=\"M42 58 A 7 7 0 1 1 33 65 A 7 7 0 0 1 42 58 Z\" fill=\"url(#musicGrad)\"></path>\n                    <path d=\"M62 53 A 7 7 0 1 1 53 60 A 7 7 0 0 1 62 53 Z\" fill=\"url(#musicGrad)\"></path>\n                    \n                    <path d=\"M40 60 L 40 32 L 60 27 L 60 55\" fill=\"none\" stroke=\"url(#musicGrad)\" stroke-width=\"4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"></path>\n                    <path d=\"M40 42 L 60 37\" fill=\"none\" stroke=\"url(#musicGrad)\" stroke-width=\"3\" stroke-linecap=\"round\"></path>\n                  </g>\n                </svg>', 2, 1, 1);
INSERT INTO `video_partitions` (`id`, `created_at`, `updated_at`, `name`, `icon`, `sort_order`, `is_active`, `is_submittable`) VALUES (4, '2026-01-14 14:59:06.711', '2026-03-23 20:59:01.672', '游戏', '<svg viewBox=\"0 0 100 100\" xmlns=\"http://www.w3.org/2000/svg\" width=\"100%\" height=\"100%\">\n                  <defs>\n                    <linearGradient id=\"gameGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n                      <stop offset=\"0%\" stop-color=\"#FF0080\"></stop>\n                      <stop offset=\"100%\" stop-color=\"#00F2FE\"></stop>\n                    </linearGradient>\n                    <filter id=\"gameGlow\" x=\"-50%\" y=\"-50%\" width=\"200%\" height=\"200%\">\n                      <feGaussianBlur stdDeviation=\"3\" result=\"blur\"></feGaussianBlur>\n                      <feMerge><feMergeNode in=\"blur\"></feMergeNode><feMergeNode in=\"SourceGraphic\"></feMergeNode></feMerge>\n                    </filter>\n                  </defs>\n                  <style>\n                    .game-pad { transform-origin: 50px 50px; animation: game-hover 3.5s infinite alternate ease-in-out; filter: url(#gameGlow); }\n                    .game-btn { animation: game-flash 2s infinite alternate; fill: rgba(255,255,255,0.2); }\n                    .game-btn1 { animation-delay: 0s; } .game-btn2 { animation-delay: 0.5s; }\n                    .game-stick { animation: game-wiggle 4s infinite; transform-origin: center; }\n                    @keyframes game-hover { 0% { transform: translateY(3px) rotate(-2deg) scale(0.98); } 100% { transform: translateY(-3px) rotate(2deg) scale(1.02); } }\n                    @keyframes game-flash { 0%, 40% { fill: rgba(255,255,255,0.2); } 50%, 100% { fill: #ffffff; } }\n                    @keyframes game-wiggle { 0%, 100% { transform: translate(0,0); } 10%, 30% { transform: translate(-2px, -2px); } 20%, 40% { transform: translate(2px, 2px); } 50% { transform: translate(0,0); } }\n                  </style>\n                  <g class=\"game-pad\">\n                    \n                    <path d=\"M 20 35 C 5 35, 5 65, 25 65 C 35 65, 40 55, 50 55 C 60 55, 65 65, 75 65 C 95 65, 95 35, 80 35 L 20 35 Z\" fill=\"rgba(255,255,255,0.03)\" stroke=\"url(#gameGrad)\" stroke-width=\"3\" stroke-linejoin=\"round\"></path>\n                    \n                    \n                    <path d=\"M 25 35 L 25 30 C 25 25, 35 25, 35 35\" fill=\"none\" stroke=\"url(#gameGrad)\" stroke-width=\"2.5\" stroke-linecap=\"round\"></path>\n                    <path d=\"M 75 35 L 75 30 C 75 25, 65 25, 65 35\" fill=\"none\" stroke=\"url(#gameGrad)\" stroke-width=\"2.5\" stroke-linecap=\"round\"></path>\n                    \n                    \n                    <g fill=\"url(#gameGrad)\">\n                        <rect x=\"23\" y=\"43\" width=\"10\" height=\"4\" rx=\"1\"></rect>\n                        <rect x=\"26\" y=\"40\" width=\"4\" height=\"10\" rx=\"1\"></rect>\n                    </g>\n                    \n                    \n                    <circle cx=\"70\" cy=\"49\" r=\"2.5\" class=\"game-btn game-btn1\"></circle>\n                    <circle cx=\"77\" cy=\"42\" r=\"2.5\" class=\"game-btn game-btn2\"></circle>\n                    <circle cx=\"70\" cy=\"35\" r=\"2.5\" class=\"game-btn game-btn1\"></circle>\n                    <circle cx=\"63\" cy=\"42\" r=\"2.5\" class=\"game-btn game-btn2\"></circle>\n                    \n                    \n                    <circle cx=\"40\" cy=\"50\" r=\"5\" fill=\"none\" stroke=\"url(#gameGrad)\" stroke-width=\"2\" class=\"game-stick\"></circle>\n                    <circle cx=\"60\" cy=\"50\" r=\"5\" fill=\"none\" stroke=\"url(#gameGrad)\" stroke-width=\"2\" class=\"game-stick\" style=\"animation-delay: 0.5s\"></circle>\n                  </g>\n                </svg>', 3, 1, 1);
INSERT INTO `video_partitions` (`id`, `created_at`, `updated_at`, `name`, `icon`, `sort_order`, `is_active`, `is_submittable`) VALUES (5, '2026-01-14 14:59:06.711', '2026-03-23 20:59:09.174', '知识', '<svg viewBox=\"0 0 100 100\" xmlns=\"http://www.w3.org/2000/svg\" width=\"100%\" height=\"100%\">\n                  <defs>\n                    <linearGradient id=\"knowGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n                      <stop offset=\"0%\" stop-color=\"#89f7fe\"></stop>\n                      <stop offset=\"100%\" stop-color=\"#66a6ff\"></stop>\n                    </linearGradient>\n                    <filter id=\"knowGlow\" x=\"-50%\" y=\"-50%\" width=\"200%\" height=\"200%\">\n                      <feGaussianBlur stdDeviation=\"3.5\" result=\"blur\"></feGaussianBlur>\n                      <feMerge><feMergeNode in=\"blur\"></feMergeNode><feMergeNode in=\"SourceGraphic\"></feMergeNode></feMerge>\n                    </filter>\n                  </defs>\n                  <style>\n                    .know-book { transform-origin: 50px 75px; animation: know-float 4s infinite ease-in-out; }\n                    .know-page { transform-origin: 50px 75px; animation: know-flip 3s infinite ease-in-out; fill: none; stroke: url(#knowGrad); stroke-width: 1.5; opacity: 0.5; }\n                    .know-beam { stroke-dasharray: 20 15; animation: know-beam-flow 2s infinite linear; opacity: 0.8; }\n                    .know-core { filter: url(#knowGlow); animation: know-pulse 2s infinite alternate; }\n                    @keyframes know-float { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-5px); } }\n                    @keyframes know-flip { 0% { transform: scaleX(1); } 50% { transform: scaleX(0.1); opacity: 1; stroke-width: 2.5; } 100% { transform: scaleX(1); opacity: 0.5; } }\n                    @keyframes know-beam-flow { to { stroke-dashoffset: -35; } }\n                    @keyframes know-pulse { 0% { r: 3; opacity: 0.8; } 100% { r: 5; opacity: 1; fill: #ffffff; } }\n                  </style>\n                  \n                  \n                  <path d=\"M 50 60 L 25 15\" stroke=\"url(#knowGrad)\" stroke-width=\"2\" class=\"know-beam\"></path>\n                  <path d=\"M 50 60 L 50 5\" stroke=\"url(#knowGrad)\" stroke-width=\"2\" class=\"know-beam\" style=\"animation-duration: 2.5s;\"></path>\n                  <path d=\"M 50 60 L 75 15\" stroke=\"url(#knowGrad)\" stroke-width=\"2\" class=\"know-beam\" style=\"animation-duration: 1.5s;\"></path>\n                  \n                  \n                  <circle cx=\"50\" cy=\"50\" r=\"4\" fill=\"url(#knowGrad)\" class=\"know-core\"></circle>\n                  \n                  <g class=\"know-book\">\n                    \n                    <path d=\"M 50 75 Q 35 65, 15 70 L 15 40 Q 35 35, 50 45\" fill=\"none\" stroke=\"url(#knowGrad)\" stroke-width=\"2\" opacity=\"0.4\"></path>\n                    <path d=\"M 50 75 Q 65 65, 85 70 L 85 40 Q 65 35, 50 45\" fill=\"none\" stroke=\"url(#knowGrad)\" stroke-width=\"2\" opacity=\"0.4\"></path>\n                    \n                    <path d=\"M 50 75 Q 35 65, 15 70 L 15 50 Q 35 45, 50 55\" class=\"know-page\" style=\"animation-delay: 0s;\"></path>\n                    <path d=\"M 50 75 Q 65 65, 85 70 L 85 50 Q 65 45, 50 55\" class=\"know-page\" style=\"animation-delay: 1.5s;\"></path>\n                    \n                    <path d=\"M 50 80 Q 35 70, 15 75 L 15 55 Q 35 50, 50 60 Q 65 50, 85 55 L 85 75 Q 65 70, 50 80 Z\" fill=\"rgba(255,255,255,0.05)\" stroke=\"url(#knowGrad)\" stroke-width=\"2\" stroke-linejoin=\"round\"></path>\n                    \n                    <line x1=\"50\" y1=\"80\" x2=\"50\" y2=\"60\" stroke=\"url(#knowGrad)\" stroke-width=\"2\" stroke-linecap=\"round\"></line>\n                  </g>\n                </svg>', 4, 1, 1);
INSERT INTO `video_partitions` (`id`, `created_at`, `updated_at`, `name`, `icon`, `sort_order`, `is_active`, `is_submittable`) VALUES (6, '2026-01-14 14:59:06.711', '2026-03-23 20:59:27.240', '生活', '<svg viewBox=\"0 0 100 100\" xmlns=\"http://www.w3.org/2000/svg\" width=\"100%\" height=\"100%\">\n                  <defs>\n                    <linearGradient id=\"lifeStyleGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n                      <stop offset=\"0%\" stop-color=\"#FF9A9E\"></stop>\n                      <stop offset=\"100%\" stop-color=\"#FECFEF\"></stop>\n                    </linearGradient>\n                    <linearGradient id=\"sunGrad\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n                      <stop offset=\"0%\" stop-color=\"#FFD200\"></stop>\n                      <stop offset=\"100%\" stop-color=\"#F7971E\"></stop>\n                    </linearGradient>\n                    <filter id=\"lifeStyleGlow\" x=\"-50%\" y=\"-50%\" width=\"200%\" height=\"200%\">\n                      <feGaussianBlur stdDeviation=\"2.5\" result=\"blur\"></feGaussianBlur>\n                      <feMerge><feMergeNode in=\"blur\"></feMergeNode><feMergeNode in=\"SourceGraphic\"></feMergeNode></feMerge>\n                    </filter>\n                  </defs>\n                  <style>\n                    .polaroid-frame { transform-origin: 50px 50px; animation: polaroid-float 5s infinite alternate ease-in-out; }\n                    .polaroid-sun { animation: sun-rise 4s infinite alternate ease-in-out; filter: url(#lifeStyleGlow); }\n                    .polaroid-sparkle { transform-origin: center; animation: sparkle-pop 2s infinite alternate ease-in-out; }\n                    @keyframes polaroid-float { 0% { transform: translateY(3px) rotate(-3deg); } 100% { transform: translateY(-4px) rotate(2deg); } }\n                    @keyframes sun-rise { 0% { transform: translateY(2px); opacity: 0.8; } 100% { transform: translateY(-3px); opacity: 1; } }\n                    @keyframes sparkle-pop { 0% { transform: scale(0.5); opacity: 0.2; } 100% { transform: scale(1.2); opacity: 1; } }\n                  </style>\n                  <g class=\"polaroid-frame\">\n                    \n                    <rect x=\"25\" y=\"15\" width=\"50\" height=\"65\" rx=\"4\" fill=\"rgba(255,255,255,0.05)\" stroke=\"url(#lifeStyleGrad)\" stroke-width=\"2\"></rect>\n                    \n                    <rect x=\"30\" y=\"20\" width=\"40\" height=\"40\" rx=\"2\" fill=\"rgba(255,255,255,0.1)\"></rect>\n                    <rect x=\"30\" y=\"20\" width=\"40\" height=\"40\" rx=\"2\" fill=\"none\" stroke=\"url(#lifeStyleGrad)\" stroke-width=\"1.5\"></rect>\n                    \n                    \n                    <g transform=\"translate(30, 20)\">\n                        \n                        <clipPath id=\"photoClip\">\n                            <rect x=\"0\" y=\"0\" width=\"40\" height=\"40\" rx=\"2\"></rect>\n                        </clipPath>\n                        <g clip-path=\"url(#photoClip)\">\n                            <circle cx=\"20\" cy=\"22\" r=\"8\" fill=\"url(#sunGrad)\" class=\"polaroid-sun\"></circle>\n                            <path d=\"M 0 30 Q 10 25, 20 30 T 40 30 L 40 40 L 0 40 Z\" fill=\"url(#lifeStyleGrad)\" opacity=\"0.6\"></path>\n                            <path d=\"M -10 35 Q 0 30, 10 35 T 30 35 T 50 35 L 50 40 L -10 40 Z\" fill=\"url(#lifeStyleGrad)\"></path>\n                        </g>\n                    </g>\n                    \n                    <path d=\"M 50 72 C 50 72, 47 69, 45 69 C 43 69, 43 71, 45 73 L 50 77 L 55 73 C 57 71, 57 69, 55 69 C 53 69, 50 72, 50 72 Z\" fill=\"url(#lifeStyleGrad)\" filter=\"url(#lifeStyleGlow)\"></path>\n                  </g>\n                  \n                  \n                  <circle cx=\"20\" cy=\"30\" r=\"2\" fill=\"url(#sunGrad)\" class=\"polaroid-sparkle\" style=\"animation-delay: 0.5s\"></circle>\n                  <circle cx=\"80\" cy=\"45\" r=\"3\" fill=\"url(#lifeStyleGrad)\" class=\"polaroid-sparkle\" style=\"animation-delay: 1.2s\"></circle>\n                  <circle cx=\"25\" cy=\"70\" r=\"2.5\" fill=\"url(#lifeStyleGrad)\" class=\"polaroid-sparkle\" style=\"animation-delay: 0.8s\"></circle>\n                </svg>', 5, 1, 1);
INSERT INTO `video_partitions` (`id`, `created_at`, `updated_at`, `name`, `icon`, `sort_order`, `is_active`, `is_submittable`) VALUES (7, '2026-01-14 14:59:06.711', '2026-03-23 20:59:37.042', '科技', '<svg viewBox=\"0 0 100 100\" xmlns=\"http://www.w3.org/2000/svg\" width=\"100%\" height=\"100%\">\n                  <defs>\n                    <linearGradient id=\"techGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n                      <stop offset=\"0%\" stop-color=\"#00C6FF\"></stop>\n                      <stop offset=\"100%\" stop-color=\"#0072FF\"></stop>\n                    </linearGradient>\n                    <filter id=\"techGlow\" x=\"-50%\" y=\"-50%\" width=\"200%\" height=\"200%\">\n                      <feGaussianBlur stdDeviation=\"3\" result=\"blur\"></feGaussianBlur>\n                      <feMerge><feMergeNode in=\"blur\"></feMergeNode><feMergeNode in=\"SourceGraphic\"></feMergeNode></feMerge>\n                    </filter>\n                  </defs>\n                  <style>\n                    .tech-hex { transform-origin: 50px 50px; animation: tech-spin 10s linear infinite; }\n                    .tech-inner { transform-origin: 50px 50px; animation: tech-spin 8s linear infinite reverse; }\n                    .tech-node { filter: url(#techGlow); animation: tech-pulse 2s infinite alternate ease-in-out; }\n                    .tech-data { stroke-dasharray: 8 20; animation: tech-flow 1.5s infinite linear; }\n                    @keyframes tech-spin { 100% { transform: rotate(360deg); } }\n                    @keyframes tech-pulse { 0% { r: 3; fill: #00C6FF; opacity: 0.6; } 100% { r: 5; fill: #ffffff; opacity: 1; } }\n                    @keyframes tech-flow { to { stroke-dashoffset: -28; } }\n                  </style>\n                  \n                  <g class=\"tech-hex\">\n                    <polygon points=\"50,15 80.3,32.5 80.3,67.5 50,85 19.7,67.5 19.7,32.5\" fill=\"rgba(0,198,255,0.03)\" stroke=\"url(#techGrad)\" stroke-width=\"1.5\" opacity=\"0.6\"></polygon>\n                    <circle cx=\"50\" cy=\"15\" r=\"2\" fill=\"url(#techGrad)\"></circle>\n                    <circle cx=\"80.3\" cy=\"32.5\" r=\"2\" fill=\"url(#techGrad)\"></circle>\n                    <circle cx=\"80.3\" cy=\"67.5\" r=\"2\" fill=\"url(#techGrad)\"></circle>\n                    <circle cx=\"50\" cy=\"85\" r=\"2\" fill=\"url(#techGrad)\"></circle>\n                    <circle cx=\"19.7\" cy=\"67.5\" r=\"2\" fill=\"url(#techGrad)\"></circle>\n                    <circle cx=\"19.7\" cy=\"32.5\" r=\"2\" fill=\"url(#techGrad)\"></circle>\n                  </g>\n                  \n                  \n                  <g class=\"tech-inner\">\n                    <polygon points=\"50,30 67.3,40 67.3,60 50,70 32.7,60 32.7,40\" fill=\"none\" stroke=\"url(#techGrad)\" stroke-width=\"2\"></polygon>\n                    <line x1=\"50\" y1=\"50\" x2=\"50\" y2=\"30\" stroke=\"url(#techGrad)\" stroke-width=\"2\"></line>\n                    <line x1=\"50\" y1=\"50\" x2=\"67.3\" y2=\"60\" stroke=\"url(#techGrad)\" stroke-width=\"2\"></line>\n                    <line x1=\"50\" y1=\"50\" x2=\"32.7\" y2=\"60\" stroke=\"url(#techGrad)\" stroke-width=\"2\"></line>\n                    \n                    \n                    <polygon points=\"50,30 67.3,40 67.3,60 50,70 32.7,60 32.7,40\" fill=\"none\" stroke=\"#ffffff\" stroke-width=\"2\" class=\"tech-data\"></polygon>\n                  </g>\n                  \n                  \n                  <circle cx=\"50\" cy=\"50\" r=\"4\" fill=\"url(#techGrad)\" class=\"tech-node\"></circle>\n                </svg>', 6, 1, 1);
INSERT INTO `video_partitions` (`id`, `created_at`, `updated_at`, `name`, `icon`, `sort_order`, `is_active`, `is_submittable`) VALUES (8, '2026-01-14 14:59:06.711', '2026-03-23 20:59:44.890', '鬼畜', '<svg viewBox=\"0 0 100 100\" xmlns=\"http://www.w3.org/2000/svg\" width=\"100%\" height=\"100%\">\n                  <defs>\n                    <linearGradient id=\"kichikuGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n                      <stop offset=\"0%\" stop-color=\"#F107A3\"></stop>\n                      <stop offset=\"100%\" stop-color=\"#7B2CBF\"></stop>\n                    </linearGradient>\n                    <filter id=\"glitchGlow\" x=\"-50%\" y=\"-50%\" width=\"200%\" height=\"200%\">\n                      <feGaussianBlur stdDeviation=\"3\" result=\"blur\"></feGaussianBlur>\n                      <feMerge><feMergeNode in=\"blur\"></feMergeNode><feMergeNode in=\"SourceGraphic\"></feMergeNode></feMerge>\n                    </filter>\n                  </defs>\n                  <style>\n                    /* 极其硬核的故障抖动效果 */\n                    .tv-body { transform-origin: 50px 50px; animation: tv-float 3s infinite ease-in-out; }\n                    .glitch-layer-1 { fill: #00F2FE; animation: glitch-anim-1 2s infinite linear alternate-reverse; mix-blend-mode: screen; }\n                    .glitch-layer-2 { fill: #F107A3; animation: glitch-anim-2 2.5s infinite linear alternate-reverse; mix-blend-mode: screen; }\n                    .glitch-base { fill: #ffffff; filter: url(#glitchGlow); }\n                    .tv-static { stroke-dasharray: 5 10; animation: static-run 0.5s infinite linear; }\n                    \n                    @keyframes tv-float { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-5px); } }\n                    @keyframes static-run { to { stroke-dashoffset: -15; } }\n                    @keyframes glitch-anim-1 {\n                      0%, 100% { transform: translate(0, 0); }\n                      10% { transform: translate(-2px, 1px); }\n                      20% { transform: translate(2px, -1px); opacity: 0.8; }\n                      30% { transform: translate(0, 0); }\n                      40% { transform: translate(3px, 2px); }\n                      50% { transform: translate(-3px, -2px); opacity: 1; }\n                      60% { transform: translate(0, 0); }\n                      80% { transform: translate(-1px, 2px); }\n                    }\n                    @keyframes glitch-anim-2 {\n                      0%, 100% { transform: translate(0, 0); }\n                      15% { transform: translate(2px, -2px); }\n                      25% { transform: translate(-2px, 2px); opacity: 0.7; }\n                      35% { transform: translate(0, 0); }\n                      45% { transform: translate(-3px, -1px); }\n                      55% { transform: translate(3px, 1px); opacity: 1; }\n                      65% { transform: translate(0, 0); }\n                      85% { transform: translate(1px, -2px); }\n                    }\n                  </style>\n                  \n                  <g class=\"tv-body\">\n                    \n                    <polyline points=\"40,25 50,35 60,20\" fill=\"none\" stroke=\"url(#kichikuGrad)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"></polyline>\n                    <circle cx=\"40\" cy=\"25\" r=\"2\" fill=\"#00F2FE\"></circle>\n                    <circle cx=\"60\" cy=\"20\" r=\"2\" fill=\"#F107A3\"></circle>\n                    \n                    \n                    <rect x=\"20\" y=\"35\" width=\"60\" height=\"45\" rx=\"6\" fill=\"rgba(255,255,255,0.05)\" stroke=\"url(#kichikuGrad)\" stroke-width=\"3\"></rect>\n                    \n                    \n                    <path d=\"M 25 45 L 75 45 M 25 55 L 75 55 M 25 65 L 75 65\" fill=\"none\" stroke=\"rgba(255,255,255,0.2)\" stroke-width=\"1\" class=\"tv-static\"></path>\n                    \n                    \n                    <g transform=\"translate(0, 5)\">\n                        \n                        <g class=\"glitch-layer-1\">\n                            <rect x=\"35\" y=\"42\" width=\"6\" height=\"6\" rx=\"1\"></rect>\n                            <rect x=\"59\" y=\"42\" width=\"6\" height=\"6\" rx=\"1\"></rect>\n                            <path d=\"M 35 55 Q 50 65 65 55\" fill=\"none\" stroke=\"#00F2FE\" stroke-width=\"3\" stroke-linecap=\"round\"></path>\n                        </g>\n                        \n                        <g class=\"glitch-layer-2\">\n                            <rect x=\"35\" y=\"42\" width=\"6\" height=\"6\" rx=\"1\"></rect>\n                            <rect x=\"59\" y=\"42\" width=\"6\" height=\"6\" rx=\"1\"></rect>\n                            <path d=\"M 35 55 Q 50 65 65 55\" fill=\"none\" stroke=\"#F107A3\" stroke-width=\"3\" stroke-linecap=\"round\"></path>\n                        </g>\n                        \n                        <g class=\"glitch-base\">\n                            <rect x=\"35\" y=\"42\" width=\"6\" height=\"6\" rx=\"1\"></rect>\n                            <rect x=\"59\" y=\"42\" width=\"6\" height=\"6\" rx=\"1\"></rect>\n                            <path d=\"M 35 55 Q 50 65 65 55\" fill=\"none\" stroke=\"#ffffff\" stroke-width=\"3\" stroke-linecap=\"round\"></path>\n                        </g>\n                    </g>\n                  </g>\n                </svg>', 7, 1, 1);
INSERT INTO `video_partitions` (`id`, `created_at`, `updated_at`, `name`, `icon`, `sort_order`, `is_active`, `is_submittable`) VALUES (10, '2026-01-14 15:51:22.774', '2026-03-23 20:59:49.819', '影视', '<svg viewBox=\"0 0 100 100\" xmlns=\"http://www.w3.org/2000/svg\" width=\"100%\" height=\"100%\">\n                  <defs>\n                    <linearGradient id=\"filmGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n                      <stop offset=\"0%\" stop-color=\"#F5515F\"></stop>\n                      <stop offset=\"100%\" stop-color=\"#9F041B\"></stop>\n                    </linearGradient>\n                    <linearGradient id=\"beamGrad\" x1=\"0%\" y1=\"50%\" x2=\"100%\" y2=\"50%\">\n                      <stop offset=\"0%\" stop-color=\"rgba(245,81,95,0.6)\"></stop>\n                      <stop offset=\"100%\" stop-color=\"rgba(245,81,95,0)\"></stop>\n                    </linearGradient>\n                    <filter id=\"filmGlow\" x=\"-50%\" y=\"-50%\" width=\"200%\" height=\"200%\">\n                      <feGaussianBlur stdDeviation=\"3\" result=\"blur\"></feGaussianBlur>\n                      <feMerge><feMergeNode in=\"blur\"></feMergeNode><feMergeNode in=\"SourceGraphic\"></feMergeNode></feMerge>\n                    </filter>\n                  </defs>\n                  <style>\n                    .film-reel { transform-origin: 35px 50px; animation: reel-spin 6s infinite linear; }\n                    .film-lens { filter: url(#filmGlow); animation: lens-pulse 2s infinite alternate ease-in-out; }\n                    .film-beam { transform-origin: 65px 50px; animation: beam-flicker 0.1s infinite alternate; mix-blend-mode: screen; }\n                    @keyframes reel-spin { 100% { transform: rotate(360deg); } }\n                    @keyframes lens-pulse { 0% { fill: rgba(255,255,255,0.6); } 100% { fill: #ffffff; } }\n                    @keyframes beam-flicker { 0% { opacity: 0.8; } 100% { opacity: 0.5; } }\n                  </style>\n                  \n                  \n                  <polygon points=\"65,50 95,20 95,80\" fill=\"url(#beamGrad)\" class=\"film-beam\"></polygon>\n                  \n                  \n                  <rect x=\"15\" y=\"30\" width=\"40\" height=\"40\" rx=\"4\" fill=\"rgba(255,255,255,0.05)\" stroke=\"url(#filmGrad)\" stroke-width=\"2.5\"></rect>\n                  \n                  \n                  <g class=\"film-reel\">\n                    <circle cx=\"35\" cy=\"50\" r=\"14\" fill=\"none\" stroke=\"url(#filmGrad)\" stroke-width=\"2\"></circle>\n                    <circle cx=\"35\" cy=\"50\" r=\"3\" fill=\"url(#filmGrad)\"></circle>\n                    <line x1=\"35\" y1=\"36\" x2=\"35\" y2=\"47\" stroke=\"url(#filmGrad)\" stroke-width=\"2\"></line>\n                    <line x1=\"35\" y1=\"53\" x2=\"35\" y2=\"64\" stroke=\"url(#filmGrad)\" stroke-width=\"2\"></line>\n                    <line x1=\"21\" y1=\"50\" x2=\"32\" y2=\"50\" stroke=\"url(#filmGrad)\" stroke-width=\"2\"></line>\n                    <line x1=\"38\" y1=\"50\" x2=\"49\" y2=\"50\" stroke=\"url(#filmGrad)\" stroke-width=\"2\"></line>\n                  </g>\n\n                  \n                  <path d=\"M 55 42 L 65 38 L 65 62 L 55 58 Z\" fill=\"rgba(255,255,255,0.1)\" stroke=\"url(#filmGrad)\" stroke-width=\"2\"></path>\n                  <ellipse cx=\"65\" cy=\"50\" rx=\"3\" ry=\"12\" class=\"film-lens\"></ellipse>\n                  \n                  \n                  <rect x=\"20\" y=\"20\" width=\"4\" height=\"4\" fill=\"url(#filmGrad)\"></rect>\n                  <rect x=\"30\" y=\"20\" width=\"4\" height=\"4\" fill=\"url(#filmGrad)\"></rect>\n                  <rect x=\"40\" y=\"20\" width=\"4\" height=\"4\" fill=\"url(#filmGrad)\"></rect>\n                  <rect x=\"20\" y=\"76\" width=\"4\" height=\"4\" fill=\"url(#filmGrad)\"></rect>\n                  <rect x=\"30\" y=\"76\" width=\"4\" height=\"4\" fill=\"url(#filmGrad)\"></rect>\n                  <rect x=\"40\" y=\"76\" width=\"4\" height=\"4\" fill=\"url(#filmGrad)\"></rect>\n                </svg>', 9, 1, 1);
INSERT INTO `video_partitions` (`id`, `created_at`, `updated_at`, `name`, `icon`, `sort_order`, `is_active`, `is_submittable`) VALUES (11, '2026-03-07 01:54:01.954', '2026-03-22 03:17:29.588', 'AI', '<svg viewBox=\"0 0 100 100\" xmlns=\"http://www.w3.org/2000/svg\" width=\"100%\" height=\"100%\">\n                  <defs>\n                    <linearGradient id=\"aiGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n                      <stop offset=\"0%\" stop-color=\"#00F2FE\"></stop>\n                      <stop offset=\"100%\" stop-color=\"#4FACFE\"></stop>\n                    </linearGradient>\n                    <filter id=\"aiGlow\" x=\"-50%\" y=\"-50%\" width=\"200%\" height=\"200%\">\n                      <feGaussianBlur stdDeviation=\"3\" result=\"blur\"></feGaussianBlur>\n                      <feMerge>\n                        <feMergeNode in=\"blur\"></feMergeNode>\n                        <feMergeNode in=\"SourceGraphic\"></feMergeNode>\n                      </feMerge>\n                    </filter>\n                  </defs>\n                  <style>\n                    .ai-core { animation: ai-pulse 2s infinite alternate ease-in-out; filter: url(#aiGlow); }\n                    .ai-orb1 { transform-origin: 50px 50px; animation: ai-spin-1 6s linear infinite; }\n                    .ai-orb2 { transform-origin: 50px 50px; animation: ai-spin-2 8s linear infinite reverse; }\n                    .ai-orb3 { transform-origin: 50px 50px; animation: ai-spin-3 10s linear infinite; }\n                    @keyframes ai-pulse { \n                      0% { r: 10; opacity: 0.8; } \n                      100% { r: 13; opacity: 1; fill: #ffffff; } \n                    }\n                    @keyframes ai-spin-1 { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }\n                    @keyframes ai-spin-2 { 0% { transform: rotate(60deg); } 100% { transform: rotate(420deg); } }\n                    @keyframes ai-spin-3 { 0% { transform: rotate(120deg); } 100% { transform: rotate(480deg); } }\n                  </style>\n                  <g class=\"ai-orb1\">\n                    <ellipse cx=\"50\" cy=\"50\" rx=\"40\" ry=\"12\" fill=\"none\" stroke=\"url(#aiGrad)\" stroke-width=\"1.5\" opacity=\"0.6\"></ellipse>\n                    <circle cx=\"90\" cy=\"50\" r=\"3\" fill=\"#00F2FE\" filter=\"url(#aiGlow)\"></circle>\n                  </g>\n                  <g class=\"ai-orb2\">\n                    <ellipse cx=\"50\" cy=\"50\" rx=\"40\" ry=\"12\" fill=\"none\" stroke=\"url(#aiGrad)\" stroke-width=\"1.5\" opacity=\"0.6\"></ellipse>\n                    <circle cx=\"10\" cy=\"50\" r=\"2.5\" fill=\"#4FACFE\" filter=\"url(#aiGlow)\"></circle>\n                  </g>\n                  <g class=\"ai-orb3\">\n                    <ellipse cx=\"50\" cy=\"50\" rx=\"40\" ry=\"12\" fill=\"none\" stroke=\"url(#aiGrad)\" stroke-width=\"1.5\" opacity=\"0.6\"></ellipse>\n                    <circle cx=\"50\" cy=\"38\" r=\"3.5\" fill=\"#ffffff\" filter=\"url(#aiGlow)\"></circle>\n                  </g>\n                  <circle cx=\"50\" cy=\"50\" r=\"12\" fill=\"url(#aiGrad)\" class=\"ai-core\"></circle>\n                </svg>', 1, 1, 1);
INSERT INTO `video_partitions` (`id`, `created_at`, `updated_at`, `name`, `icon`, `sort_order`, `is_active`, `is_submittable`) VALUES (12, '2026-03-07 01:54:11.034', '2026-03-23 20:13:59.006', '哲学', '<svg viewBox=\"0 0 100 100\" xmlns=\"http://www.w3.org/2000/svg\" width=\"100%\" height=\"100%\">\n                  <defs>\n                    <linearGradient id=\"philGrad1\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n                      <stop offset=\"0%\" stop-color=\"#F6D365\"></stop>\n                      <stop offset=\"100%\" stop-color=\"#FDA085\"></stop>\n                    </linearGradient>\n                    <linearGradient id=\"philGrad2\" x1=\"100%\" y1=\"100%\" x2=\"0%\" y2=\"0%\">\n                      <stop offset=\"0%\" stop-color=\"#ffffff\"></stop>\n                      <stop offset=\"100%\" stop-color=\"#F6D365\"></stop>\n                    </linearGradient>\n                    <filter id=\"philGlow\" x=\"-50%\" y=\"-50%\" width=\"200%\" height=\"200%\">\n                        <feGaussianBlur stdDeviation=\"3\" result=\"blur\"></feGaussianBlur>\n                        <feComposite in=\"SourceGraphic\" in2=\"blur\" operator=\"over\"></feComposite>\n                    </filter>\n                  </defs>\n                  <style>\n                    .phil-shape1 { transform-origin: 35px 50px; animation: phil-breathe1 5s infinite alternate ease-in-out; }\n                    .phil-shape2 { transform-origin: 65px 50px; animation: phil-breathe2 5s infinite alternate ease-in-out; }\n                    .phil-center { transform-origin: 50px 50px; animation: phil-rotate 12s cubic-bezier(0.4, 0, 0.2, 1) infinite; filter: url(#philGlow); }\n                    @keyframes phil-breathe1 { 0% { transform: scale(1) translateX(0); stroke-width: 2; } 100% { transform: scale(1.1) translateX(-3px); stroke-width: 4; } }\n                    @keyframes phil-breathe2 { 0% { transform: scale(1) translateX(0); stroke-width: 4; } 100% { transform: scale(1.1) translateX(3px); stroke-width: 2; } }\n                    @keyframes phil-rotate { 0% { transform: rotate(0deg) scale(0.8); } 50% { transform: rotate(180deg) scale(1.1); } 100% { transform: rotate(360deg) scale(0.8); } }\n                  </style>\n                  <circle cx=\"35\" cy=\"50\" r=\"22\" fill=\"none\" stroke=\"url(#philGrad1)\" class=\"phil-shape1\"></circle>\n                  <circle cx=\"65\" cy=\"50\" r=\"22\" fill=\"none\" stroke=\"url(#philGrad2)\" opacity=\"0.7\" class=\"phil-shape2\"></circle>\n                  \n                  <path d=\"M50 32 L62 50 L50 68 L38 50 Z\" fill=\"url(#philGrad1)\" class=\"phil-center\" opacity=\"0.9\"></path>\n                  <circle cx=\"50\" cy=\"50\" r=\"4\" fill=\"#1a1a2e\" class=\"phil-center\" style=\"animation-direction: reverse;\"></circle>\n                </svg>', 1, 1, 1);
INSERT INTO `video_partitions` (`id`, `created_at`, `updated_at`, `name`, `icon`, `sort_order`, `is_active`, `is_submittable`) VALUES (13, '2026-03-07 02:21:29.148', '2026-03-23 20:57:19.104', '艺术', '<svg viewBox=\"0 0 100 100\" xmlns=\"http://www.w3.org/2000/svg\" width=\"100%\" height=\"100%\">\n                  <defs>\n                    <linearGradient id=\"artGrad1\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n                      <stop offset=\"0%\" stop-color=\"#FF0844\"></stop>\n                      <stop offset=\"100%\" stop-color=\"#FFB199\"></stop>\n                    </linearGradient>\n                    <linearGradient id=\"artGrad2\" x1=\"100%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n                      <stop offset=\"0%\" stop-color=\"#9C27B0\"></stop>\n                      <stop offset=\"100%\" stop-color=\"#3F51B5\"></stop>\n                    </linearGradient>\n                    <linearGradient id=\"artGrad3\" x1=\"50%\" y1=\"100%\" x2=\"50%\" y2=\"0%\">\n                      <stop offset=\"0%\" stop-color=\"#FFD700\"></stop>\n                      <stop offset=\"100%\" stop-color=\"#FF8C00\"></stop>\n                    </linearGradient>\n                    <filter id=\"artGlow\" x=\"-50%\" y=\"-50%\" width=\"200%\" height=\"200%\">\n                        <feGaussianBlur stdDeviation=\"6\" result=\"blur\"></feGaussianBlur>\n                        <feComposite in=\"SourceGraphic\" in2=\"blur\" operator=\"over\"></feComposite>\n                    </filter>\n                  </defs>\n                  <style>\n                    /* 使用 screen 实现色彩的高级正片叠底融合感 */\n                    .art-blob1 { transform-origin: 50px 50px; animation: art-morph1 6s infinite alternate ease-in-out; mix-blend-mode: screen; filter: url(#artGlow); }\n                    .art-blob2 { transform-origin: 50px 50px; animation: art-morph2 7s infinite alternate-reverse ease-in-out; mix-blend-mode: screen; }\n                    .art-blob3 { transform-origin: 50px 50px; animation: art-morph3 8s infinite alternate ease-in-out; mix-blend-mode: screen; }\n                    @keyframes art-morph1 { 0% { transform: translate(0,0) scale(0.9) rotate(0deg); } 100% { transform: translate(8px, -8px) scale(1.1) rotate(45deg); } }\n                    @keyframes art-morph2 { 0% { transform: translate(0,0) scale(1) rotate(0deg); } 100% { transform: translate(-10px, 5px) scale(1.15) rotate(-30deg); } }\n                    @keyframes art-morph3 { 0% { transform: translate(0,0) scale(0.8) rotate(0deg); } 100% { transform: translate(5px, 10px) scale(1.2) rotate(60deg); } }\n                  </style>\n                  \n                  <path d=\"M60,25 C75,25 85,40 85,55 C85,75 70,85 55,85 C35,85 20,70 20,55 C20,35 40,25 60,25 Z\" fill=\"url(#artGrad1)\" class=\"art-blob1\" opacity=\"0.8\"></path>\n                  <path d=\"M45,15 C65,15 80,30 80,45 C80,65 65,80 45,80 C25,80 15,60 15,45 C15,25 30,15 45,15 Z\" fill=\"url(#artGrad2)\" class=\"art-blob2\" opacity=\"0.8\"></path>\n                  <circle cx=\"50\" cy=\"55\" r=\"20\" fill=\"url(#artGrad3)\" class=\"art-blob3\" opacity=\"0.7\"></circle>\n                  \n                  <path d=\"M50,30 L52,42 L64,44 L52,46 L50,58 L48,46 L36,44 L48,42 Z\" fill=\"#ffffff\" class=\"art-blob1\"></path>\n                </svg>', 1, 1, 1);
INSERT INTO `video_partitions` (`id`, `created_at`, `updated_at`, `name`, `icon`, `sort_order`, `is_active`, `is_submittable`) VALUES (14, '2026-03-07 02:22:03.872', '2026-03-23 20:16:23.211', '数码', '<svg viewBox=\"0 0 100 100\" xmlns=\"http://www.w3.org/2000/svg\" width=\"100%\" height=\"100%\">\n                  <defs>\n                    <linearGradient id=\"digiGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n                      <stop offset=\"0%\" stop-color=\"#43E97B\"></stop>\n                      <stop offset=\"100%\" stop-color=\"#38F9D7\"></stop>\n                    </linearGradient>\n                    <filter id=\"digiGlow\" x=\"-50%\" y=\"-50%\" width=\"200%\" height=\"200%\">\n                      <feGaussianBlur stdDeviation=\"2.5\" result=\"blur\"></feGaussianBlur>\n                      <feMerge>\n                        <feMergeNode in=\"blur\"></feMergeNode>\n                        <feMergeNode in=\"SourceGraphic\"></feMergeNode>\n                      </feMerge>\n                    </filter>\n                  </defs>\n                  <style>\n                    .digi-chip { transform-origin: 50px 50px; animation: digi-hover 4s infinite ease-in-out; }\n                    .digi-line { stroke-dasharray: 10 15; animation: digi-flow 1.5s infinite linear; }\n                    .digi-core { filter: url(#digiGlow); animation: digi-pulse 2s infinite alternate ease-in-out; }\n                    @keyframes digi-hover { 0%, 100% { transform: translateY(0) rotateX(0deg); } 50% { transform: translateY(-5px) rotateX(10deg); } }\n                    @keyframes digi-flow { to { stroke-dashoffset: -25; } }\n                    @keyframes digi-pulse { 0% { opacity: 0.5; fill: #43E97B; transform: scale(0.9); } 100% { opacity: 1; fill: #ffffff; transform: scale(1.1); } }\n                  </style>\n                  <g class=\"digi-chip\">\n                    \n                    <rect x=\"25\" y=\"25\" width=\"50\" height=\"50\" rx=\"6\" fill=\"rgba(255,255,255,0.05)\" stroke=\"url(#digiGrad)\" stroke-width=\"2\"></rect>\n                    \n                    <rect x=\"33\" y=\"33\" width=\"34\" height=\"34\" rx=\"4\" fill=\"url(#digiGrad)\" opacity=\"0.15\"></rect>\n                    <rect x=\"33\" y=\"33\" width=\"34\" height=\"34\" rx=\"4\" fill=\"none\" stroke=\"url(#digiGrad)\" stroke-width=\"1\" opacity=\"0.5\"></rect>\n                    \n                    <rect x=\"42\" y=\"42\" width=\"16\" height=\"16\" rx=\"3\" fill=\"url(#digiGrad)\" class=\"digi-core\" transform-origin=\"50px 50px\"></rect>\n                    \n                    \n                    <path d=\"M40 25 L40 10 M50 25 L50 10 M60 25 L60 10\" stroke=\"url(#digiGrad)\" stroke-width=\"2\" stroke-linecap=\"round\" class=\"digi-line\"></path>\n                    <path d=\"M40 75 L40 90 M50 75 L50 90 M60 75 L60 90\" stroke=\"url(#digiGrad)\" stroke-width=\"2\" stroke-linecap=\"round\" class=\"digi-line\" style=\"animation-direction: reverse;\"></path>\n                    <path d=\"M25 40 L10 40 M25 50 L10 50 M25 60 L10 60\" stroke=\"url(#digiGrad)\" stroke-width=\"2\" stroke-linecap=\"round\" class=\"digi-line\" style=\"animation-delay: 0.5s;\"></path>\n                    <path d=\"M75 40 L90 40 M75 50 L90 50 M75 60 L90 60\" stroke=\"url(#digiGrad)\" stroke-width=\"2\" stroke-linecap=\"round\" class=\"digi-line\" style=\"animation-direction: reverse; animation-delay: 0.5s;\"></path>\n                  </g>\n                </svg>', 1, 1, 1);
INSERT INTO `video_partitions` (`id`, `created_at`, `updated_at`, `name`, `icon`, `sort_order`, `is_active`, `is_submittable`) VALUES (15, '2026-03-07 02:22:08.940', '2026-03-23 20:58:33.968', '美食', '<svg viewBox=\"0 0 100 100\" xmlns=\"http://www.w3.org/2000/svg\" width=\"100%\" height=\"100%\">\n                  <defs>\n                    <linearGradient id=\"foodGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n                      <stop offset=\"0%\" stop-color=\"#FF8008\"></stop>\n                      <stop offset=\"100%\" stop-color=\"#FFC837\"></stop>\n                    </linearGradient>\n                    <filter id=\"foodGlow\" x=\"-50%\" y=\"-50%\" width=\"200%\" height=\"200%\">\n                      <feGaussianBlur stdDeviation=\"3\" result=\"blur\"></feGaussianBlur>\n                      <feMerge><feMergeNode in=\"blur\"></feMergeNode><feMergeNode in=\"SourceGraphic\"></feMergeNode></feMerge>\n                    </filter>\n                  </defs>\n                  <style>\n                    .food-cloche { transform-origin: 50px 50px; animation: food-float 4s infinite ease-in-out; filter: url(#foodGlow); }\n                    .food-steam { stroke-dasharray: 20; stroke-dashoffset: 20; animation: food-steam-rise 2.5s infinite linear; }\n                    .steam1 { animation-delay: 0s; }\n                    .steam2 { animation-delay: 0.8s; }\n                    .steam3 { animation-delay: 1.6s; }\n                    @keyframes food-float { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-4px); } }\n                    @keyframes food-steam-rise { 0% { stroke-dashoffset: 20; opacity: 0; transform: translateY(5px); } 30% { opacity: 1; } 100% { stroke-dashoffset: -20; opacity: 0; transform: translateY(-15px); } }\n                  </style>\n                  \n                  <path d=\"M 35 45 Q 30 35, 35 25 Q 40 15, 35 5\" fill=\"none\" stroke=\"url(#foodGrad)\" stroke-width=\"2\" class=\"food-steam steam1\" stroke-linecap=\"round\"></path>\n                  <path d=\"M 50 40 Q 45 30, 50 20 Q 55 10, 50 0\" fill=\"none\" stroke=\"url(#foodGrad)\" stroke-width=\"2.5\" class=\"food-steam steam2\" stroke-linecap=\"round\"></path>\n                  <path d=\"M 65 45 Q 60 35, 65 25 Q 70 15, 65 5\" fill=\"none\" stroke=\"url(#foodGrad)\" stroke-width=\"2\" class=\"food-steam steam3\" stroke-linecap=\"round\"></path>\n                  \n                  <g class=\"food-cloche\">\n                    <path d=\"M 20 60 C 20 25, 80 25, 80 60\" fill=\"rgba(255,200,55,0.05)\" stroke=\"url(#foodGrad)\" stroke-width=\"3\"></path>\n                    <circle cx=\"50\" cy=\"22\" r=\"4\" fill=\"url(#foodGrad)\"></circle>\n                    <path d=\"M 12 60 L 88 60 C 88 65, 12 65, 12 60 Z\" fill=\"url(#foodGrad)\"></path>\n                  </g>\n                </svg>', 1, 1, 1);
INSERT INTO `video_partitions` (`id`, `created_at`, `updated_at`, `name`, `icon`, `sort_order`, `is_active`, `is_submittable`) VALUES (16, '2026-03-07 02:22:13.279', '2026-03-23 20:58:45.227', '人生', '<svg viewBox=\"0 0 100 100\" xmlns=\"http://www.w3.org/2000/svg\" width=\"100%\" height=\"100%\">\n                  <defs>\n                    <linearGradient id=\"lifeGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n                      <stop offset=\"0%\" stop-color=\"#10A881\"></stop>\n                      <stop offset=\"100%\" stop-color=\"#00F2FE\"></stop>\n                    </linearGradient>\n                    <filter id=\"lifeGlow\" x=\"-50%\" y=\"-50%\" width=\"200%\" height=\"200%\">\n                      <feGaussianBlur stdDeviation=\"3\" result=\"blur\"></feGaussianBlur>\n                      <feMerge><feMergeNode in=\"blur\"></feMergeNode><feMergeNode in=\"SourceGraphic\"></feMergeNode></feMerge>\n                    </filter>\n                  </defs>\n                  <style>\n                    .life-node { animation: life-pulse 2.5s infinite alternate ease-in-out; filter: url(#lifeGlow); }\n                    .life-line { animation: life-breathe 5s infinite alternate ease-in-out; transform-origin: center bottom; }\n                    .life-aura { animation: life-pulse 3s infinite alternate-reverse ease-in-out; }\n                    @keyframes life-pulse { 0% { r: 2.5; opacity: 0.6; } 100% { r: 4.5; opacity: 1; fill: #ffffff; } }\n                    @keyframes life-breathe { 0% { transform: scale(1) translateY(0); } 100% { transform: scale(1.03) translateY(-2px); } }\n                  </style>\n                  <g class=\"life-line\">\n                    \n                    <path d=\"M50 85 L50 60\" fill=\"none\" stroke=\"url(#lifeGrad)\" stroke-width=\"3\" stroke-linecap=\"round\"></path>\n                    \n                    <path d=\"M50 60 L30 40\" fill=\"none\" stroke=\"url(#lifeGrad)\" stroke-width=\"2.5\" stroke-linecap=\"round\"></path>\n                    <path d=\"M50 60 L70 40\" fill=\"none\" stroke=\"url(#lifeGrad)\" stroke-width=\"2.5\" stroke-linecap=\"round\"></path>\n                    \n                    <path d=\"M30 40 L20 20\" fill=\"none\" stroke=\"url(#lifeGrad)\" stroke-width=\"2\" stroke-linecap=\"round\"></path>\n                    <path d=\"M30 40 L40 25\" fill=\"none\" stroke=\"url(#lifeGrad)\" stroke-width=\"2\" stroke-linecap=\"round\"></path>\n                    <path d=\"M70 40 L60 25\" fill=\"none\" stroke=\"url(#lifeGrad)\" stroke-width=\"2\" stroke-linecap=\"round\"></path>\n                    <path d=\"M70 40 L80 20\" fill=\"none\" stroke=\"url(#lifeGrad)\" stroke-width=\"2\" stroke-linecap=\"round\"></path>\n                    \n                    \n                    <circle cx=\"50\" cy=\"60\" r=\"3\" fill=\"url(#lifeGrad)\" class=\"life-node\" style=\"animation-delay: 0s\"></circle>\n                    <circle cx=\"30\" cy=\"40\" r=\"3\" fill=\"url(#lifeGrad)\" class=\"life-node\" style=\"animation-delay: 0.4s\"></circle>\n                    <circle cx=\"70\" cy=\"40\" r=\"3\" fill=\"url(#lifeGrad)\" class=\"life-node\" style=\"animation-delay: 0.4s\"></circle>\n                    <circle cx=\"20\" cy=\"20\" r=\"3\" fill=\"url(#lifeGrad)\" class=\"life-node\" style=\"animation-delay: 0.8s\"></circle>\n                    <circle cx=\"40\" cy=\"25\" r=\"3\" fill=\"url(#lifeGrad)\" class=\"life-node\" style=\"animation-delay: 0.8s\"></circle>\n                    <circle cx=\"60\" cy=\"25\" r=\"3\" fill=\"url(#lifeGrad)\" class=\"life-node\" style=\"animation-delay: 0.8s\"></circle>\n                    <circle cx=\"80\" cy=\"20\" r=\"3\" fill=\"url(#lifeGrad)\" class=\"life-node\" style=\"animation-delay: 0.8s\"></circle>\n                  </g>\n                  \n                  <ellipse cx=\"50\" cy=\"85\" rx=\"15\" ry=\"3\" fill=\"url(#lifeGrad)\" opacity=\"0.3\" filter=\"url(#lifeGlow)\" class=\"life-aura\"></ellipse>\n                </svg>', 1, 1, 1);